------------------
---- MONITORS ----
------------------

-- See https://wiki.hypr.land/Configuring/Basics/Monitors/
-- Izquierda: DP-1 vertical
hl.monitor({ output = "DP-1",     mode = "preferred", position = "0x0",      scale = 1, transform = 3 })
-- Centro: HDMI-A-1 horizontal (centrado verticalmente respecto a los verticales)
hl.monitor({ output = "HDMI-A-1", mode = "preferred", position = "1080x420", scale = 1 })
-- Derecha: DP-2 vertical
hl.monitor({ output = "DP-2",     mode = "preferred", position = "3000x0",   scale = 1, transform = 1 })


---------------------
---- MY PROGRAMS ----
---------------------

-- Set programs that you use
local terminal    = "wezterm"
local fileManager = "dolphin"
local menu        = "wofi --show drun"


-------------------
---- AUTOSTART ----
-------------------

-- See https://wiki.hypr.land/Configuring/Basics/Autostart/

-- Autostart necessary processes (notification daemon, status bar, etc.)
hl.on("hyprland.start", function ()
    hl.exec_cmd("waybar")                                                                -- barra
    hl.exec_cmd("swaync")                                                                -- notificaciones
    hl.exec_cmd("/usr/lib/x86_64-linux-gnu/libexec/polkit-kde-authentication-agent-1")   -- diálogos de contraseña
    hl.exec_cmd("nm-applet --indicator")                                                 -- applet de red
    hl.exec_cmd("wl-paste --watch cliphist store")                                       -- historial de portapapeles
    hl.exec_cmd("hypridle")                                                              -- bloqueo/apagado por inactividad
    hl.exec_cmd("hyprpaper")                                                             -- fondo de pantalla
end)


-------------------------------
---- ENVIRONMENT VARIABLES ----
-------------------------------

-- See https://wiki.hypr.land/Configuring/Advanced-and-Cool/Environment-variables/

hl.env("XCURSOR_SIZE", "24")
hl.env("HYPRCURSOR_SIZE", "24")

-- NVIDIA (RTX 3060) - ver https://wiki.hypr.land/Nvidia/
hl.env("LIBVA_DRIVER_NAME", "nvidia")
hl.env("__GLX_VENDOR_LIBRARY_NAME", "nvidia")
hl.env("NVD_BACKEND", "direct")
hl.env("ELECTRON_OZONE_PLATFORM_HINT", "auto")

-- Tema oscuro global
hl.env("QT_QPA_PLATFORMTHEME", "qt6ct")   -- apps Qt usan qt6ct (paleta oscura)
hl.env("GTK_THEME", "Adwaita-dark")        -- fuerza tema oscuro en apps GTK

-- Para que wofi/launchers vean apps de snap y flatpak en el menú
hl.env("XDG_DATA_DIRS", "/var/lib/flatpak/exports/share:/var/lib/snapd/desktop:/usr/local/share:/usr/share")


